export function ActionCard({
  title = "{{title}}",
  body = "{{body}}",
  actionLabel = "{{actionLabel}}",
  variant = "{{variant}}",
  color = "{{color}}",
}) {
  const wrap = {
    primary: { background: color, border: "none" },
    secondary: { background: "#FAF7F2", border: "1.5px solid " + color },
    ghost: { background: "transparent", border: "1px dashed #24143033" },
  }[variant] ?? {};
  const actionBg = variant === "primary" ? "#241430" : color;
  const actionColor = variant === "primary" ? "#FAF7F2" : "#241430";
  return (
    <article style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 300, borderRadius: 12, padding: 18, ...wrap }}>
      <h3 style={{ margin: "0 0 6px", fontSize: 16 }}>{title}</h3>
      <p style={{ margin: "0 0 14px", fontSize: 13, opacity: 0.85 }}>{body}</p>
      <button type="button" style={{ border: "none", borderRadius: 8, padding: "8px 16px", fontSize: 13, fontWeight: 600, cursor: "pointer", background: actionBg, color: actionColor }}>
        {actionLabel}
      </button>
    </article>
  );
}
